/* From Uiverse.io by Galahhad - Tags: gradient, switch */
/* checkbox settings 👇 */

.__UIV_SCOPE__ .switch {
  /* global */
  --total_transition_duration: .3s;
  /* switch */
  --slider_width: 2.875em;
  --slider_height: 1.5em;
  --slider_light_bg: linear-gradient(90deg, #f32a85 0%, #f19d36 100%);
  --slider_night_bg: linear-gradient(90deg, #1701a1 0%, #af0693 75%);
  --slider_offset: calc((var(--slider_height) - var(--circle_diameter)) / 2);
  --slider_radius: calc(var(--slider_height) / 2);
  /* circle */
  --circle_diameter: 1.125em;
  --circle_rotation: 360deg;
  /* svg */
  --svg_width: var(--circle_diameter);
  --sun-color: #fff;
  --moon-color: #fff;
}

.__UIV_SCOPE__ .switch input {
  display: none;
}

.__UIV_SCOPE__ .slider svg {
  position: absolute;
  height: auto;
  color: var(--svg-color);
  transition: var(--total_transition_duration) ease;
  width: 100%;
}

.__UIV_SCOPE__ .circle svg.sun {
  transform: scale(1);
  color: var(--sun-color);
}

.__UIV_SCOPE__ .circle svg.moon {
  transform: scale(0);
  color: var(--moon-color);
  width: calc(100% - 2px);
}

.__UIV_SCOPE__ .slider {
  display: inline-block;
  width: var(--slider_width);
  height: var(--slider_height);
  border-radius: var(--slider_radius);
  position: relative;
  cursor: pointer;
  transition: var(--total_transition_duration) ease;
  overflow: hidden;
}

.__UIV_SCOPE__ .slider::before,
.__UIV_SCOPE__ .slider::after {
  content: "";
  position: absolute;
  inset: 0;
  transition: var(--total_transition_duration) ease;
}

/* ::before and ::after backgrounds are needed for smooth 
transition of gradients otherwise there is no way :\ */
.__UIV_SCOPE__ .slider::before {
  opacity: 0;
  background: var(--slider_night_bg);
}

.__UIV_SCOPE__ .slider::after {
  opacity: 1;
  background: var(--slider_light_bg);
}

/* ------------ */

.__UIV_SCOPE__ .circle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--circle_diameter);
  height: var(--circle_diameter);
  position: absolute;
  top: var(--slider_offset);
  left: var(--slider_offset);
  transition: var(--total_transition_duration) ease;
  z-index: 10;
}

/* actions */

.__UIV_SCOPE__ .switch input:checked+.slider::before {
  opacity: 1;
}

.__UIV_SCOPE__ .switch input:checked+.slider::after {
  opacity: 0;
}

.__UIV_SCOPE__ .switch input:active+.slider .circle {
  transform: scale(0.9);
}

.__UIV_SCOPE__ .switch input:checked+.slider .circle {
  left: calc(100% - var(--circle_diameter) - var(--slider_offset));
}

.__UIV_SCOPE__ .switch input:checked+.slider .sun {
  transform: scale(0) rotate(var(--circle_rotation));
}

.__UIV_SCOPE__ .switch input:checked+.slider .moon {
  transform: scale(1) rotate(var(--circle_rotation));
}
